<?php
namespace Nakhostin\PerformanceEngine\CSS;
final class FontPreloadPlanner { public function plan( FontManifest $manifest, int $limit = 2 ): array { $data = $manifest->to_array(); $fonts = (array) ( $data['fonts'] ?? $data['required'] ?? array() ); if ( empty( $fonts ) ) { foreach ( (array) ( $data['families'] ?? array() ) as $family ) { foreach ( (array) ( $family['faces'] ?? array() ) as $face ) { if ( empty( $face['required'] ) ) { continue; } foreach ( (array) ( $face['sources'] ?? array() ) as $source ) { $fonts[] = array( 'url' => $source['url'] ?? '', 'critical' => true ); } } } } usort( $fonts, static function ( array $a, array $b ): int { $aw = false !== stripos( (string) ( $a['url'] ?? $a['src'] ?? '' ), '.woff2' ) ? 0 : 1; $bw = false !== stripos( (string) ( $b['url'] ?? $b['src'] ?? '' ), '.woff2' ) ? 0 : 1; return $aw <=> $bw; } ); $result = array(); foreach ( $fonts as $font ) { $url = esc_url_raw( (string) ( $font['url'] ?? $font['src'] ?? '' ) ); if ( '' === $url || empty( $font['critical'] ) ) { continue; } $result[] = array( 'url' => $url, 'type' => false !== stripos( $url, '.woff2' ) ? 'font/woff2' : 'font/woff' ); if ( count( $result ) >= max( 0, min( 2, $limit ) ) ) { break; } } return $result; } }
